1	import nodemailer from "nodemailer";
2	import { db } from "./db";
3	import {
4	  renderTemplate,
5	  recordEmail,
6	  wrapEmail,
7	  emailButton,
8	  appUrl,
9	  emailHeading,
10	  emailParagraph,
11	  emailEyebrow,
12	  emailNote,
13	  emailPanel,
14	  emailBanner,
15	  emailKeyValue,
16	  type Accent,
17	} from "./email-render";
18	import { renderInvoiceHTML } from "./invoices";
19	import { emails as catalogEmails, type BuiltEmail } from "./email-templates";
