21	/**
22	 * SMTP config comes from the Setting table (admin-editable) with env fallback.
23	 * Keys: smtp_host, smtp_port, smtp_user, smtp_pass, smtp_from, smtp_secure.
24	 * If nothing is configured, falls back to a local sendmail/Postfix relay on :25.
25	 */
26	async function loadSmtp() {
27	  const rows = await db.setting.findMany({
28	    where: { key: { in: ["smtp_host", "smtp_port", "smtp_user", "smtp_pass", "smtp_from", "smtp_secure"] } },
29	  });
30	  const s = Object.fromEntries(rows.map((r) => [r.key, r.value]));
31	  const host = s.smtp_host || process.env.SMTP_HOST || "";
32	  const from = s.smtp_from || process.env.SMTP_FROM || `Nxeon <no-reply@${(process.env.APP_URL ?? "localhost").replace(/^https?:\/\//, "")}>`;
33	  return {
34	    host,
35	    port: Number(s.smtp_port || process.env.SMTP_PORT || 587),
36	    user: s.smtp_user || process.env.SMTP_USER || "",
37	    pass: s.smtp_pass || process.env.SMTP_PASS || "",
38	    secure: (s.smtp_secure ?? process.env.SMTP_SECURE) === "true",
39	    from,
40	  };
41	}
42	
43	export async function mailConfigured(): Promise<boolean> {
44	  const c = await loadSmtp();
45	  return !!c.host || process.env.NXEON_LOCAL_MAIL === "1";
46	}
47	
48	function transport(c: Awaited<ReturnType<typeof loadSmtp>>) {
49	  if (!c.host) {
50	    // Local MTA fallback (Postfix/sendmail on the host)
51	    return nodemailer.createTransport({ sendmail: true, newline: "unix", path: "/usr/sbin/sendmail" });
52	  }
53	  // When the SMTP host is an internal IP (e.g. the mail VM at 10.20.0.10) but the
54	  // server presents a cert for its hostname (mail.nxeon.cloud), TLS validation
55	  // fails on an IP mismatch. `SMTP_TLS_SERVERNAME` lets us keep cert verification
56	  // on while telling TLS the name to validate against (and sets SNI accordingly).
57	  const servername = process.env.SMTP_TLS_SERVERNAME || undefined;
58	  return nodemailer.createTransport({
59	    host: c.host,
60	    port: c.port,
61	    secure: c.secure,
62	    auth: c.user ? { user: c.user, pass: c.pass } : undefined,
63	    ...(servername ? { tls: { servername } } : {}),
64	  });
65	}
