67	/** Template keys whose emails ship the itemised invoice as an attachment. */
68	const INVOICE_ATTACH_TEMPLATES = new Set(["receipt", "invoice_new", "renewal_reminder"]);
69	
70	export type MailAttachment = { filename: string; content: string | Buffer; contentType?: string };
71	
72	/**
73	 * Build the invoice attachment for an email. There is no PDF library installed
74	 * (and we can't add dependencies), so we attach the branded, print-ready
75	 * invoice HTML produced by `lib/invoices.ts` — recipients open it and use their
76	 * browser's Print → Save as PDF, matching the on-site download route.
77	 */
78	async function invoiceAttachment(invoiceId: string): Promise<MailAttachment | null> {
79	  try {
80	    const invoice = await db.invoice.findUnique({
81	      where: { id: invoiceId },
82	      include: { user: { select: { name: true, email: true } } },
83	    });
84	    if (!invoice) return null;
85	    const html = renderInvoiceHTML(invoice, invoice.user);
86	    const number = String(invoice.number).padStart(5, "0");
87	    return { filename: `nxeon-invoice-${number}.html`, content: html, contentType: "text/html; charset=utf-8" };
88	  } catch (e) {
89	    console.error("[mailer] failed to build invoice attachment:", e);
90	    return null;
91	  }
92	}
