94	export type SendMailOpts = {
95	  to: string;
96	  /** Explicit subject. Optional when `template` is provided. */
97	  subject?: string;
98	  /** Explicit pre-rendered HTML. Optional when `template` is provided. */
99	  html?: string;
100	  text?: string;
101	  /** DB template key — when set (and no explicit `html`), the body is rendered via `renderTemplate`. */
102	  template?: string;
103	  /** Variables for `{{placeholders}}` when rendering from a template. */
104	  vars?: Record<string, unknown>;
105	  /** Attribution for the EmailLog row. */
106	  userId?: string | null;
107	  /** When set, attaches the invoice (auto for receipt/invoice_new/renewal_reminder templates). */
108	  invoiceId?: string;
109	  /** Extra attachments. */
110	  attachments?: MailAttachment[];
111	};
112	
113	/**
114	 * Send an email. Never throws — logs and returns false on failure so callers
115	 * don't break flows. EVERY attempt is written to `EmailLog` (SENT on success,
116	 * FAILED + error otherwise) for the admin Logs viewer.
117	 */
118	export async function sendMail(opts: SendMailOpts): Promise<boolean> {
119	  // Resolve subject/html: prefer explicit values, otherwise render the template.
120	  let subject = opts.subject ?? "";
121	  let html = opts.html ?? "";
122	  const templateKey = opts.template ?? null;
123	
124	  if (templateKey && !opts.html) {
125	    const rendered = await renderTemplate(templateKey, opts.vars ?? {});
126	    subject = opts.subject ?? rendered.subject;
127	    html = rendered.html;
128	  }
129	
130	  // Assemble attachments (invoice auto-attaches for the relevant templates).
131	  const attachments: MailAttachment[] = [...(opts.attachments ?? [])];
132	  const wantInvoice = opts.invoiceId && (!templateKey || INVOICE_ATTACH_TEMPLATES.has(templateKey));
133	  if (wantInvoice && opts.invoiceId) {
134	    const att = await invoiceAttachment(opts.invoiceId);
135	    if (att) attachments.push(att);
136	  }
137	
138	  try {
139	    const c = await loadSmtp();
140	    if (!c.host && process.env.NXEON_LOCAL_MAIL !== "1") {
141	      console.warn("[mailer] not configured — skipping email:", subject);
142	      await recordEmail(opts.to, subject, templateKey, html, "FAILED", "SMTP not configured", opts.userId);
143	      return false;
144	    }
145	    const t = transport(c);
146	    await t.sendMail({
147	      from: c.from,
148	      to: opts.to,
149	      subject,
150	      html,
151	      text: opts.text ?? html.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim(),
152	      attachments: attachments.length ? attachments : undefined,
153	    });
154	    await recordEmail(opts.to, subject, templateKey, html, "SENT", null, opts.userId);
155	    return true;
156	  } catch (e) {
157	    console.error("[mailer] send failed:", e);
158	    await recordEmail(opts.to, subject, templateKey, html, "FAILED", String((e as Error)?.message ?? e), opts.userId);
159	    return false;
160	  }
161	}
162	
163	/**
164	 * Preferred path for DB-templated sends: render `key` with `vars`, send, log,
165	 * and (for billing templates) attach the invoice. Thin convenience over
166	 * `sendMail` for new callers.
167	 */
168	export async function sendTemplate(
169	  key: string,
170	  to: string,
171	  vars: Record<string, unknown> = {},
172	  opts: { userId?: string | null; invoiceId?: string; attachments?: MailAttachment[] } = {},
173	): Promise<boolean> {
174	  return sendMail({ to, template: key, vars, userId: opts.userId, invoiceId: opts.invoiceId, attachments: opts.attachments });
175	}
176	
177	export async function sendTestMail(to: string): Promise<{ ok: boolean; error?: string }> {
178	  try {
179	    const c = await loadSmtp();
180	    const t = transport(c);
181	    const html = layout("SMTP test", "<p>Your Nxeon mail configuration works. 🎉</p>");
182	    await t.sendMail({ from: c.from, to, subject: "Nxeon SMTP test", html });
183	    await recordEmail(to, "Nxeon SMTP test", null, html, "SENT");
184	    return { ok: true };
185	  } catch (e: any) {
186	    return { ok: false, error: String(e?.message ?? e).slice(0, 300) };
187	  }
188	}
