209	// ---- Transactional templates ----
210	//
211	// The full transactional catalog lives in `lib/email-templates.ts` (30+
212	// templates, all composed from the shared inline-styled components). It is
213	// re-exported here as `emails` so every existing call site — `import { emails }
214	// from "@/lib/mailer"` — keeps working unchanged. Each entry returns
215	// `{ template, subject, html }`; the six original signatures are preserved.
216	export type { BuiltEmail };
217	
218	// ===========================================================================
219	// Card billing & dunning templates
220	//
221	// Renewals apply wallet credit first, then auto-charge the customer's saved
222	// card for the remainder. When that charge fails we retry on day 1, 3 and 5 and
223	// only suspend once the retries are exhausted. These templates carry that flow.
224	//
225	// They live here rather than in `lib/email-templates.ts` only because this file
226	// is the one owned by the card-billing change; they are built with the same
227	// `build()` shape and the same shared components, so they render identically to
228	// the rest of the catalog.
229	// ===========================================================================
230	
231	/**
232	 * Number of automatic retries in the dunning sequence (day 1, day 3, day 5).
233	 * `paymentRetryFailed` uses it to tell the customer how many attempts are left,
234	 * so the worker's retry schedule and this copy must agree.
235	 */
236	export const DUNNING_RETRY_ATTEMPTS = 3;
237	
238	/**
239	 * Same composition helper as `lib/email-templates.ts` (which keeps its copy
240	 * module-private): eyebrow → heading → body blocks → single CTA → optional
241	 * footnote, wrapped with a preheader by the shared shell.
242	 */
243	function build(opts: {
244	  template: string;
245	  subject: string;
246	  preheader: string;
247	  eyebrow?: string;
248	  accent?: Accent;
249	  heading: string;
250	  blocks: string[];
251	  cta?: { href: string; label: string; accent?: Accent };
252	  note?: string;
253	}): BuiltEmail {
254	  const parts: string[] = [];
255	  if (opts.eyebrow) parts.push(emailEyebrow(opts.eyebrow, opts.accent ?? "violet"));
256	  parts.push(emailHeading(opts.heading));
257	  parts.push(...opts.blocks);
258	  if (opts.cta) parts.push(emailButton(opts.cta.href, opts.cta.label, opts.cta.accent ?? "violet"));
259	  if (opts.note) parts.push(emailNote(opts.note));
260	  return {
261	    template: opts.template,
262	    subject: opts.subject,
263	    html: wrapEmail(parts.join("\n"), { preheader: opts.preheader }),
264	  };
265	}
266	
267	/** Masked card display used wherever we echo the saved card back. */
268	const cardLabel = (last4: string) => `&bull;&bull;&bull;&bull;&nbsp;${last4}`;
269	
270	/** `MM/YYYY` from the raw Stripe expiry fields — never guessed, only formatted. */
271	const expiryLabel = (expMonth: number, expYear: number) => `${String(expMonth).padStart(2, "0")}/${expYear}`;
272	
273	/** Reassurance line reused across the dunning sequence. Nothing is suspended yet. */
274	const stillRunning = (hostname: string, extra = "") =>
275	  emailBanner(`<b>${hostname}</b> is still running. Nothing has been suspended.${extra ? ` ${extra}` : ""}`, "success");
276	
277	const legacyPaymentFailed = catalogEmails.paymentFailed;
278	type LegacyPaymentFailedArgs = Parameters<typeof legacyPaymentFailed>[0];
279	
280	/**
281	 * Card charge declined — FIRST failure of the dunning sequence.
282	 *
283	 * Overloaded so the original catalog shape (`{ amount, reason, updateUrl? }`,
284	 * still used by the admin template previewer) keeps working alongside the new
285	 * renewal-dunning shape.
286	 */
287	function paymentFailed(a: LegacyPaymentFailedArgs): BuiltEmail;
288	function paymentFailed(
289	  hostname: string,
290	  amountFormatted: string,
291	  last4: string,
292	  retryDateFormatted: string,
293	  billingUrl: string,
294	): BuiltEmail;
295	function paymentFailed(
296	  a: string | LegacyPaymentFailedArgs,
297	  amountFormatted?: string,
298	  last4?: string,
299	  retryDateFormatted?: string,
300	  billingUrl?: string,
301	): BuiltEmail {
302	  if (typeof a !== "string") return legacyPaymentFailed(a);
303	  const hostname = a;
304	  const amount = amountFormatted ?? "";
305	  const card = last4 ?? "";
306	  const retryDate = retryDateFormatted ?? "";
307	  const href = billingUrl ?? `${appUrl()}/dashboard/billing`;
308	  return build({
309	    template: "payment_failed",
310	    subject: `Card declined for ${hostname} — we'll retry ${retryDate}`,
311	    preheader: `${hostname} is still running. We'll try the card again on ${retryDate}.`,
312	    eyebrow: "Payment issue",
313	    accent: "warn",
314	    heading: "We couldn't charge your card",
315	    blocks: [
316	      emailParagraph(
317	        `The renewal payment for <b>${hostname}</b> didn't go through. Declines are usually something on the bank's side — a routine fraud check, a spending limit, or a card that's been reissued — so this often isn't anything you did.`,
318	      ),
319	      stillRunning(hostname),
320	      emailPanel(
321	        emailKeyValue([
322	          ["Server", hostname],
323	          ["Amount due", amount],
324	          ["Card", cardLabel(card)],
325	          ["Next attempt", retryDate],
326	        ]),
327	        "warn",
328	      ),
329	      emailParagraph(
330	        `We'll try the same card again on <b>${retryDate}</b>. If you'd rather not wait, update your card and we'll charge it straight away.`,
331	      ),
332	    ],
333	    cta: { href, label: "Update payment method", accent: "warn" },
334	    note: "If your bank asked you to approve the charge, approving it is enough. Anything else — just reply to this email and our team will take a look.",
335	  });
336	}
