338	const billingEmails = {
339	  /** Successful auto-charge against the saved card. */
340	  paymentReceipt: (amountFormatted: string, description: string, last4: string): BuiltEmail =>
341	    build({
342	      template: "payment_receipt",
343	      subject: `Receipt for ${amountFormatted} — card ending ${last4}`,
344	      preheader: `We charged ${amountFormatted} to your saved card. Everything is running as normal.`,
345	      eyebrow: "Receipt",
346	      accent: "success",
347	      heading: "Payment received",
348	      blocks: [
349	        emailParagraph(
350	          "Your renewal has been paid automatically using the card saved on your account. Everything is running as normal — there's nothing you need to do.",
351	        ),
352	        emailPanel(
353	          emailKeyValue([
354	            ["Amount", `<span style="color:#15a34a;">${amountFormatted}</span>`],
355	            ["For", description],
356	            ["Card", cardLabel(last4)],
357	          ]),
358	          "success",
359	        ),
360	        emailParagraph("Any wallet credit on your account was applied first; the amount above is what we charged to the card."),
361	      ],
362	      cta: { href: `${appUrl()}/dashboard/invoices`, label: "View invoices" },
363	      note: "Keep this email for your records, or download the itemised invoice from your dashboard at any time.",
364	    }),
365	
366	  /** First declined charge in the dunning sequence (see the overloads above). */
367	  paymentFailed,
368	
369	  /** A later retry in the dunning sequence was declined. */
370	  paymentRetryFailed: (
371	    hostname: string,
372	    amountFormatted: string,
373	    attempt: number,
374	    finalDateFormatted: string,
375	    billingUrl: string,
376	  ): BuiltEmail => {
377	    const remaining = Math.max(0, DUNNING_RETRY_ATTEMPTS - attempt);
378	    const remainingLine =
379	      remaining > 0
380	        ? `We'll try ${remaining} more time${remaining === 1 ? "" : "s"} before then.`
381	        : "That was the last automatic attempt.";
382	    return build({
383	      template: "payment_retry_failed",
384	      subject: `Payment retry ${attempt} declined for ${hostname} — still running until ${finalDateFormatted}`,
385	      preheader: `${hostname} stays online until ${finalDateFormatted}. ${remainingLine}`,
386	      eyebrow: `Retry ${attempt} declined`,
387	      accent: "warn",
388	      heading: "Your card was declined again",
389	      blocks: [
390	        emailParagraph(
391	          `We tried the saved card for <b>${hostname}</b> again and it was declined. If the card is fine on your end, it's worth asking your bank whether they're blocking the charge — that's the usual cause at this stage.`,
392	        ),
393	        stillRunning(hostname, `It stays online until <b>${finalDateFormatted}</b>.`),
394	        emailPanel(
395	          emailKeyValue([
396	            ["Server", hostname],
397	            ["Amount due", amountFormatted],
398	            ["Attempt", String(attempt)],
399	            ["Attempts remaining", String(remaining)],
400	            ["Suspends on", finalDateFormatted],
401	          ]),
402	          "warn",
403	        ),
404	        emailParagraph(
405	          `${remainingLine} If the balance is still unpaid on <b>${finalDateFormatted}</b>, <b>${hostname}</b> will be suspended — your data stays intact and paying restores it.`,
406	        ),
407	        emailParagraph("Updating your card now settles the balance immediately and stops the remaining retries."),
408	      ],
409	      cta: { href: billingUrl, label: "Update payment method", accent: "warn" },
410	      note: "If something about this charge looks wrong, or you need a little more time, reply to this email — we'd rather work it out with you.",
411	    });
412	  },
413	
414	  /** Stripe returned `requires_action` — the customer must complete 3-D Secure. */
415	  paymentActionRequired: (hostname: string, amountFormatted: string, authUrl: string): BuiltEmail =>
416	    build({
417	      template: "payment_action_required",
418	      subject: `Confirm the ${amountFormatted} payment for ${hostname} with your bank`,
419	      preheader: `${hostname} is still running. Your bank needs one quick confirmation to finish the payment.`,
420	      eyebrow: "Confirmation needed",
421	      accent: "info",
422	      heading: "Your bank needs to confirm this payment",
423	      blocks: [
424	        emailParagraph(
425	          `Your card issuer asked for an extra verification step before the renewal payment for <b>${hostname}</b> can complete. This is a routine security check on their side, and it takes less than a minute.`,
426	        ),
427	        stillRunning(hostname, "Confirming the payment keeps it that way."),
428	        emailPanel(
429	          emailKeyValue([
430	            ["Server", hostname],
431	            ["Amount", amountFormatted],
432	            ["Waiting on", "Bank confirmation (3-D Secure)"],
433	          ]),
434	        ),
435	        emailParagraph("Use the button below to confirm with your bank. We'll finish the payment as soon as they approve it."),
436	      ],
437	      cta: { href: authUrl, label: "Confirm payment with your bank" },
438	      note: `This confirmation link is unique to this payment and expires after a short while. If it's already expired, open <a href="${appUrl()}/dashboard/billing" style="color:#6f47f5;">Billing</a> and we'll start a fresh attempt.`,
439	    }),
440	
441	  /** Final retry failed — the last warning before the server is suspended. */
442	  paymentFinalNotice: (hostname: string, amountFormatted: string, billingUrl: string): BuiltEmail =>
443	    build({
444	      template: "payment_final_notice",
445	      subject: `Final notice for ${hostname} — ${amountFormatted} still unpaid`,
446	      preheader: `${hostname} is still running, but this is the last notice before it's suspended.`,
447	      eyebrow: "Final notice",
448	      accent: "danger",
449	      heading: "Last notice before suspension",
450	      blocks: [
451	        emailParagraph(
452	          `We've now tried the saved card for <b>${hostname}</b> as many times as we can, and it's still being declined. We've run out of automatic attempts, so this is the last message before the server has to be paused.`,
453	        ),
454	        stillRunning(hostname, `Paying the outstanding <b>${amountFormatted}</b> keeps it online.`),
455	        emailPanel(
456	          emailKeyValue([
457	            ["Server", hostname],
458	            ["Outstanding", amountFormatted],
459	            ["Status", "Running — awaiting payment"],
460	          ]),
461	          "danger",
462	        ),
463	        emailParagraph(
464	          "If the server is suspended it stops serving traffic, but nothing is deleted — your data and configuration stay exactly as they are, and settling the balance brings it straight back.",
465	        ),
466	        emailParagraph("Paying now, or switching to a different card, avoids the suspension entirely."),
467	      ],
468	      cta: { href: billingUrl, label: "Settle the balance", accent: "danger" },
469	      note: "If the charge looks wrong, or you need a few more days, reply to this email before the suspension date — we'd much rather sort it out with you than pause anything.",
470	    }),
471	
472	  /** Proactive heads-up that the card saved for auto-renewal is about to expire. */
473	  cardExpiringSoon: (last4: string, expMonth: number, expYear: number, billingUrl: string): BuiltEmail =>
474	    build({
475	      template: "card_expiring_soon",
476	      subject: `Your card ending ${last4} expires ${expiryLabel(expMonth, expYear)}`,
477	      preheader: "Nothing is wrong today — just a heads-up so your next renewal goes through.",
478	      eyebrow: "Card expiring",
479	      accent: "warn",
480	      heading: "Your saved card expires soon",
481	      blocks: [
482	        emailParagraph(
483	          `The card we use for automatic renewals expires on <b>${expiryLabel(expMonth, expYear)}</b>. Saving an up-to-date card now means your next renewal goes through without anyone having to think about it.`,
484	        ),
485	        emailBanner("All of your services are running normally. There's nothing wrong with your account today.", "success"),
486	        emailPanel(
487	          emailKeyValue([
488	            ["Card", cardLabel(last4)],
489	            ["Expires", expiryLabel(expMonth, expYear)],
490	          ]),
491	          "warn",
492	        ),
493	        emailParagraph(
494	          "If your bank has already sent a replacement, adding it takes about a minute. If the card has been renewed with the same number, just update the expiry date.",
495	        ),
496	      ],
497	      cta: { href: billingUrl, label: "Update card", accent: "warn" },
498	      note: "We only charge the card for renewals you've already agreed to, and only for the amount your wallet credit doesn't cover.",
499	    }),
500	};
501	
502	/**
503	 * The complete catalog: everything from `lib/email-templates.ts` plus the card
504	 * billing / dunning templates above. Exported under the same name so every
505	 * `import { emails } from "@/lib/mailer"` call site keeps working unchanged.
506	 */
507	export const emails = { ...catalogEmails, ...billingEmails };
508	export type EmailKey = keyof typeof emails;
509	
510	// Re-exported so other modules can build DB-templated bodies consistently.
511	export { wrapEmail, emailButton };
512

1	// Pure, dependency-free wallet/card split math shared by the client wizards
2	// (DeployWizard, ResizePicker) and the server actions (payAndDeploy,
3	// resizeServer). Keeping it here — with NO server-only imports — guarantees the
4	// split the customer SEES is byte-for-byte the split that gets CHARGED.
5	
6	/**
7	 * Stripe rejects card charges under ~$0.50. We never send a card amount below
8	 * this; when the natural remainder would fall under it we leave exactly this
9	 * much on the card and apply slightly less wallet credit (see walletSplit).
10	 */
11	export const STRIPE_MIN_CENTS = 50;
12	
13	export type WalletSplit = {
14	  /** Cents taken from the customer's existing wallet balance. */
15	  walletApplied: number;
16	  /** Cents charged to the card (0 = fully paid from wallet, no Stripe). */
17	  cardCents: number;
18	  /** True when we bumped the card up to STRIPE_MIN_CENTS (reducing wallet). */
19	  clampedForStripeMin: boolean;
20	};
21	
22	/**
23	 * Split a due amount between the wallet and the card, honoring the customer's
24	 * "apply my balance" toggle and Stripe's minimum-charge floor.
25	 *
26	 * - `useWallet` off  → everything on the card.
27	 * - wallet covers all → cardCents = 0 (caller pays entirely from wallet, no Stripe).
28	 * - partial cover     → walletApplied = min(balance, due), card = the remainder.
29	 * - tiny remainder    → if 0 < card < STRIPE_MIN_CENTS and the wallet can't cover
30	 *   the whole thing, reduce walletApplied so exactly STRIPE_MIN_CENTS lands on the
31	 *   card (never send Stripe a sub-minimum charge). Integer-cent exact throughout.
32	 */
33	export function walletSplit(opts: {
34	  dueCents: number;
35	  balanceCents: number;
36	  useWallet: boolean;
37	}): WalletSplit {
38	  const dueCents = Math.max(0, Math.round(opts.dueCents));
39	  const balanceCents = Math.max(0, Math.round(opts.balanceCents));
40	  if (dueCents <= 0) return { walletApplied: 0, cardCents: 0, clampedForStripeMin: false };
41	
42	  let walletApplied = opts.useWallet ? Math.min(balanceCents, dueCents) : 0;
43	  let cardCents = dueCents - walletApplied;
44	  let clampedForStripeMin = false;
45	
46	  // A tiny non-zero card remainder that Stripe would reject. This only happens
47	  // when the wallet can't cover the whole charge (otherwise cardCents === 0), so
48	  // the least-surprising fix is to leave STRIPE_MIN_CENTS on the card and apply a
49	  // touch less wallet. Guarded so walletApplied can never go negative.
50	  if (cardCents > 0 && cardCents < STRIPE_MIN_CENTS && dueCents >= STRIPE_MIN_CENTS) {
51	    walletApplied = dueCents - STRIPE_MIN_CENTS;
52	    cardCents = STRIPE_MIN_CENTS;
53	    clampedForStripeMin = true;
54	  }
55	  return { walletApplied, cardCents, clampedForStripeMin };
56	}
