29	          name="enabled"
30	          checked={enabled}
31	          onChange={(e) => setEnabled(e.target.checked)}
32	        />
33	        <span className="font-medium">Automatically top up my wallet</span>
34	      </label>
35	
36	      <div className={`grid gap-3 sm:grid-cols-2 ${enabled ? "" : "pointer-events-none opacity-50"}`}>
37	        <div>
38	          <label className="label">When balance drops below (USD)</label>
