59	          />
60	        </div>
61	      </div>
62	
63	      <div className="flex flex-wrap items-center gap-3">
64	        <button className="btn-primary" disabled={pending}>
65	          {pending ? "Saving…" : "Save preferences"}
66	        </button>
67	        {state?.error && <span className="text-sm text-red-400">{state.error}</span>}
68	        {state?.ok && <span className="text-sm text-emerald-300">Preferences saved.</span>}
69	      </div>
70	
71	      <p className="rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-xs text-slate-400">
72	        Requires a saved card — charging is handled automatically once a payment method is on file.
73	      </p>
74	    </form>
75	  );
76	}
