import type { Prisma } from "@prisma/client";

export class InsufficientBalanceError extends Error {
  constructor() {
    super("INSUFFICIENT_BALANCE");
    this.name = "InsufficientBalanceError";
  }
}

/**
 * Atomically debit a wallet inside a transaction. The conditional updateMany
 * (balanceCents >= cents) prevents the read-check-then-decrement race that could
 * otherwise drive balances negative under concurrent spend. Throws
 * InsufficientBalanceError (rolling back the tx) if funds are insufficient.
 */
export async function debitWallet(
  tx: Prisma.TransactionClient,
  userId: string,
  cents: number
): Promise<void> {
  if (cents <= 0) return;
  const res = await tx.user.updateMany({
    where: { id: userId, balanceCents: { gte: cents } },
    data: { balanceCents: { decrement: cents } },
  });
  if (res.count === 0) throw new InsufficientBalanceError();
}
