// Single fulfilment path for a paid Stripe Checkout session, shared by BOTH the
// success-redirect route and the webhook. Plain server module (not "use server").
//
// WHY THIS EXISTS (2026-07-25)
// Fulfilment used to live in `app/api/stripe/confirm/route.ts` and was gated on
// whether `creditCheckoutSession()` returned true. That boolean is true only for
// the caller that won the race to insert the wallet credit — and the webhook
// calls the same function and discards the result. So:
//
//   * Race: the webhook's insert lands first, the confirm request gets P2002,
//     `credited === false`, and the redirect quietly lands on an empty page.
//     $249 charged, $249 credited, no server, no error, no notification.
//   * Deterministic: the customer closes the tab before `success_url` resolves,
//     so the confirm route never runs at all. Same outcome, 100% reproducible.
//
// Stripe's own guidance is explicit that a browser redirect must not be the
// fulfilment trigger. Now BOTH callers run this, and a `FulfilledSession` row —
// its own marker, not a side effect of crediting — decides the single winner.

import { db } from "./db";
import {
  creditCheckoutSession,
  getCheckoutOrderIntent,
  getCheckoutResizeIntent,
  getCheckoutDiskExpandIntent,
} from "./stripe";
import { placeOrder } from "./order";
import { applyResize } from "./resize";
import { applyDiskExpand } from "./disk-expand";

export type FulfilResult = {
  /** Where the browser should end up. The webhook ignores this. */
  redirect: string;
  /** True when THIS call performed the fulfilment work. */
  fulfilled: boolean;
  kind: "order" | "resize" | "diskExpand" | "topup" | "none";
  error?: string;
};

/**
 * Claim exclusive responsibility for fulfilling `sessionId`.
 * Returns false when another caller already holds the claim — the UNIQUE index,
 * not a read-then-write check, is what makes this safe under concurrency.
 */
async function claim(sessionId: string, kind: string): Promise<boolean> {
  try {
    await db.fulfilledSession.create({ data: { stripeSessionId: sessionId, kind } });
    return true;
  } catch (e) {
    if ((e as { code?: string })?.code === "P2002") return false; // someone else has it
    throw e;
  }
}

async function settle(sessionId: string, status: "DONE" | "FAILED", detail?: string) {
  await db.fulfilledSession
    .update({ where: { stripeSessionId: sessionId }, data: { status, detail: detail?.slice(0, 500) } })
    .catch(() => {});
}

/**
 * Credit the wallet and fulfil whatever the session was for, exactly once.
 * Safe to call repeatedly and concurrently from the redirect and the webhook.
 */
export async function fulfilCheckoutSession(sessionId: string, base = ""): Promise<FulfilResult> {
  // Crediting is separately idempotent (UNIQUE stripeSessionId on the wallet
  // transaction). We deliberately IGNORE its return value now — it reports who
  // won the credit race, which is not the same question as "has this been
  // fulfilled", and conflating the two was the bug.
  await creditCheckoutSession(sessionId).catch(() => false);

  const order = await getCheckoutOrderIntent(sessionId);
  if (order) {
    if (!(await claim(sessionId, "order"))) {
      return { redirect: `${base}/dashboard/servers`, fulfilled: false, kind: "order" };
    }
    try {
      const user = await db.user.findUnique({ where: { id: order.userId } });
      if (!user) throw new Error("user not found for paid order");
      const serverId = await placeOrder(user, order.intent);
      await settle(sessionId, "DONE", serverId);
      return { redirect: `${base}/dashboard/servers/${serverId}`, fulfilled: true, kind: "order" };
    } catch (e) {
      // Payment is captured and the funds are in the wallet — record the failure
      // so it is reconcilable rather than invisible, and tell the customer.
      const msg = String((e as Error)?.message ?? e);
      await settle(sessionId, "FAILED", msg);
      await db.notification
        .create({
          data: {
            userId: order.userId,
            title: "Payment received — we couldn't finish setting up your server",
            body: "Your payment is safe and sitting in your wallet. Our team has been alerted; deploy again or contact support and we'll sort it out.",
            href: "/dashboard/billing",
          },
        })
        .catch(() => {});
      return { redirect: `${base}/dashboard/deploy?paid=1`, fulfilled: false, kind: "order", error: msg };
    }
  }

  const resize = await getCheckoutResizeIntent(sessionId);
  if (resize) {
    const back = `${base}/dashboard/servers/${resize.serverId}`;
    if (!(await claim(sessionId, "resize"))) {
      return { redirect: back, fulfilled: false, kind: "resize" };
    }
    try {
      await applyResize({
        serverId: resize.serverId,
        planId: resize.planId,
        actorUserId: resize.userId,
        chargeCents: resize.chargeCents,
      });
      await settle(sessionId, "DONE", resize.serverId);
      return { redirect: back, fulfilled: true, kind: "resize" };
    } catch (e) {
      const msg = String((e as Error)?.message ?? e);
      await settle(sessionId, "FAILED", msg);
      return { redirect: `${back}?paid=1`, fulfilled: false, kind: "resize", error: msg };
    }
  }

  const expand = await getCheckoutDiskExpandIntent(sessionId);
  if (expand) {
    const back = `${base}/dashboard/servers/${expand.serverId}`;
    if (!(await claim(sessionId, "diskExpand"))) {
      return { redirect: `${back}?tab=resize`, fulfilled: false, kind: "diskExpand" };
    }
    try {
      await applyDiskExpand({
        serverId: expand.serverId,
        addGB: expand.addGB,
        actorUserId: expand.userId,
        chargeCents: expand.chargeCents,
      });
      await settle(sessionId, "DONE", expand.serverId);
      return { redirect: `${back}?tab=resize`, fulfilled: true, kind: "diskExpand" };
    } catch (e) {
      const msg = String((e as Error)?.message ?? e);
      await settle(sessionId, "FAILED", msg);
      return { redirect: `${back}?paid=1`, fulfilled: false, kind: "diskExpand", error: msg };
    }
  }

  // Plain wallet top-up: crediting above is the whole job.
  return { redirect: `${base}/dashboard/billing?paid=1`, fulfilled: true, kind: "topup" };
}

