"use client";

import { useActionState, useState } from "react";
import { topUp } from "@/lib/actions";
import { Badge } from "@/components/ui/primitives";

const PRESETS = [10, 25, 50, 100];

function DemoTopUp() {
  const [state, action, pending] = useActionState(topUp, {});
  return (
    <div>
      <div className="mb-3 flex items-center gap-2">
        <Badge tone="amber">demo gateway</Badge>
        <span className="text-xs text-slate-500">
          Card payments are not configured — funds are credited instantly for testing.
        </span>
      </div>
      <form action={action} className="flex items-end gap-3">
        <div>
          <label className="label">Amount (USD)</label>
          <input
            className="input w-36"
            name="amount"
            type="number"
            min={1}
            max={1000}
            step="0.01"
            defaultValue={25}
          />
        </div>
        <button className="btn-primary" disabled={pending}>
          {pending ? "Adding…" : "Add funds"}
        </button>
        {state?.error && <span className="text-sm text-red-400">{state.error}</span>}
      </form>
    </div>
  );
}

export function AddFunds() {
  const [amount, setAmount] = useState<string>("25");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [demoMode, setDemoMode] = useState(false);

  if (demoMode) return <DemoTopUp />;

  const checkout = async () => {
    setBusy(true);
    setError(null);
    try {
      const res = await fetch("/api/stripe/checkout", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ amount: Number(amount) }),
      });
      const json: { url?: string; error?: string } = await res.json().catch(() => ({}));
      if (json.url) {
        window.location.href = json.url;
        return;
      }
      const msg = json.error ?? "Checkout failed — try again.";
      if (msg.toLowerCase().includes("not configured")) {
        setDemoMode(true);
      } else {
        setError(msg);
      }
    } catch {
      setError("Network error — try again.");
    }
    setBusy(false);
  };

  const n = Number(amount);
  const valid = Number.isFinite(n) && n >= 5 && n <= 5000;

  return (
    <div>
      <div className="flex flex-wrap items-end gap-3">
        <div>
          <label className="label">Amount (USD)</label>
          <div className="flex items-center gap-2">
            {PRESETS.map((p) => (
              <button
                key={p}
                type="button"
                onClick={() => setAmount(String(p))}
                className={`rounded-lg border px-2.5 py-1.5 text-xs font-semibold transition-colors ${
                  amount === String(p)
                    ? "border-brand-400/60 bg-brand-500/15 text-brand-200"
                    : "border-white/10 bg-white/[0.03] text-slate-400 hover:text-white"
                }`}
              >
                ${p}
              </button>
            ))}
            <input
              className="input w-28"
              type="number"
              min={5}
              max={5000}
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
            />
          </div>
        </div>
        <button className="btn-primary" onClick={() => void checkout()} disabled={busy || !valid}>
          {busy ? "Redirecting…" : "Add funds"}
        </button>
      </div>
      {!valid && amount !== "" && (
        <p className="mt-2 text-xs text-amber-300">Amount must be between $5 and $5000.</p>
      )}
      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
      <p className="mt-2 text-xs text-slate-500">Secure card checkout powered by Stripe.</p>
    </div>
  );
}

