input.content:
// Saved-card / off-session charging primitives for subscription renewals.
//
// WHY THIS FILE EXISTS
// Until now a renewal could only debit the wallet (`worker/billing.ts` ->
// `debitWallet`). A customer with a perfectly good card on file was suspended the
// moment their wallet emptied, because `User.stripePaymentMethodId` was never
// written and never read. Everything needed to charge a card lives here; the
// worker owns the *policy* (when to retry, when to suspend), this module owns the
// *mechanics* (attach a card, charge it, credit the wallet for what it paid).
//
// THE MONEY MODEL — identical to checkout, deliberately
// Checkout applies wallet credit first and puts only the remainder on the card
// (`lib/wallet-split.ts`). Renewals now do the same: the card is charged the
// remainder, that exact amount is CREDITED to the wallet, and the existing
// CAS-guarded renewal transaction debits the FULL renewal from the wallet. So the
// wallet is always the thing that pays the bill and the card is always just a way
// to fund the wallet — one money path, already proven, and a partial failure can
// never half-apply a renewal.
//
// Plain server module (NOT "use server"): imported by the worker, by server
// actions and by server components. `lib/stripe.ts` is not modified by this file.

import type Stripe from "stripe";
import { db } from "./db";
import { stripe, stripeConfigured } from "./stripe";
import { STRIPE_MIN_CENTS } from "./wallet-split";
import { invoiceCreateData } from "./invoices";
import { vpsTerm, vpsTermPriceCents } from "./billing-terms";
import { extraDiskCentsAt } from "./extra-disk";

/* ------------------------------------------------------------------ *
 * Small shared helpers
 * ------------------------------------------------------------------ */

function appBase(): string {
  return process.env.APP_URL ?? "http://localhost:3000";
}

/** Audit actions used to decide whether an unclaimed Stripe card may be adopted. */
export const CARD_SETUP_STARTED = "card.setup_started";
export const CARD_REMOVED = "card.removed";

/** How long a "I clicked Add card" intent stays good for the adoption backstop. */
const SETUP_INTENT_TTL_DAYS = 7;

export type CardDisplay = {
  brand: string | null;
  last4: string | null;
  expMonth: number | null;
  expYear: number | null;
};

/** "Visa ···· 4242, expires 04/28" — one formatter for UI, email and audit text. */
export function cardDisplayLabel(card: CardDisplay): string | null {
  if (!card.last4) return null;
  const brand = brandLabel(card.brand);
  const expiry =
    card.expMonth && card.expYear
      ? `, expires ${String(card.expMonth).padStart(2, "0")}/${String(card.expYear).slice(-2)}`
      : "";
  return `${brand} ···· ${card.last4}${expiry}`;
}

/** Stripe brand ids are lowercase slugs ("visa", "amex", "unionpay"). */
export function brandLabel(brand: string | null | undefined): string {
  const map: Record<string, string> = {
    visa: "Visa",
    mastercard: "Mastercard",
    amex: "American Express",
    discover: "Discover",
    diners: "Diners Club",
    jcb: "JCB",
    unionpay: "UnionPay",
    cartes_bancaires: "Cartes Bancaires",
    eftpos_au: "Eftpos",
    link: "Link",
  };
  if (!brand) return "Card";
  return map[brand] ?? brand.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
}

/**
 * A card is valid THROUGH the last day of its expiry month, so it stops working
 * at the first instant of the following month. Getting this off by a month would
 * either nag customers a month early or warn them after the renewal already failed.
 */
export function cardExpiresAt(expMonth: number, expYear: number): Date {
  return new Date(Date.UTC(expYear, expMonth, 1));
}

/* ------------------------------------------------------------------ *
 * Renewal pricing — ONE formula, two callers
 * ------------------------------------------------------------------ */

/**
 * What a renewal costs. Lives here (rather than being copied a third time)
 * because BOTH the worker sweep and the customer-facing "settle the balance"
 * link have to quote the same number — `renewNow` and the sweep already carry
 * the comment "the two renewal paths must never disagree", and a self-service
 * pay link that quotes a different total than the sweep charges is exactly how
 * that goes wrong.
 *
 * Pure: prices are passed in so the worker can read the admin settings once per
 * sweep instead of once per server.
 */
export type RenewalCharge = {
  months: number;
  totalCents: number;
  /** The extra-root-disk portion, which gets its own invoice line. */
  extraDiskCents: number;
  extraDiskMonthlyCents: number;
  /** Human label for the invoice / receipt ("Nebula VPS" or the game plan name). */
  label: string;
};

export type PricedServer = {
  termMonths: number;
  extraDiskGB: number;
  plan: { name: string; priceCents: number };
  gamePlan: { name: string; priceCents: number; termMonths: number } | null;
  dedicatedIp: unknown | null;
};

export function renewalCharge(
  server: PricedServer,
  prices: { ipMonthlyCents: number; extraDiskPerGbCents: number },
): RenewalCharge {
  const isGame = !!server.gamePlan;
  const months = isGame ? server.gamePlan!.termMonths : vpsTerm(server.termMonths).months;
  // Extra root disk is billed EVERY cycle at the current per-GB price. Game plans
  // are a flat all-in price and never carry the add-on lines.
  const extraDiskMonthlyCents = isGame ? 0 : extraDiskCentsAt(server.extraDiskGB, prices.extraDiskPerGbCents);
  const extraDiskCents = extraDiskMonthlyCents * months;
  const totalCents = isGame
    ? server.gamePlan!.priceCents
    : vpsTermPriceCents(server.plan.priceCents, months) +
      // Bill the IP surcharge only when the server ACTUALLY holds a dedicated IP,
      // not off the intent flag — a NAT-fallback server must never be charged for
      // an IP it never received.
      (server.dedicatedIp ? prices.ipMonthlyCents * months : 0) +
      extraDiskCents;
  return {
    months,
    totalCents,
    extraDiskCents,
    extraDiskMonthlyCents,
    label: isGame ? server.gamePlan!.name : `${server.plan.name} VPS`,
  };
}

/* ------------------------------------------------------------------ *
 * Stripe customer + saving a card
 * ------------------------------------------------------------------ */

export type CardUser = {
  id: string;
  email: string;
  name?: string | null;
  stripeCustomerId: string | null;
  stripePaymentMethodId: string | null;
};

/** True when this account can actually be charged off-session right now. */
export function hasChargeableCard(user: {
  stripeCustomerId: string | null;
  stripePaymentMethodId: string | null;
}): boolean {
  return stripeConfigured() && !!user.stripeCustomerId && !!user.stripePaymentMethodId;
}

/**
 * Get-or-create the Stripe customer for an account and remember its id.
 *
 * `User.stripeCustomerId` has no UNIQUE constraint (the schema is frozen), so two
 * concurrent "Add card" clicks could otherwise mint two Stripe customers for one
 * person and strand the card on whichever one lost. The idempotency key — derived
 * only from our own user id — is what stops that: Stripe replays the first
 * customer instead of creating a second.
 */
export async function ensureStripeCustomer(user: CardUser): Promise<string> {
  if (user.stripeCustomerId) return user.stripeCustomerId;
  const fresh = await db.user.findUnique({
    where: { id: user.id },
    select: { stripeCustomerId: true },
  });
  if (fresh?.stripeCustomerId) return fresh.stripeCustomerId;

  const customer = await stripe().customers.create(
    {
      email: user.email,
      name: user.name || undefined,
      metadata: { nxeonUserId: user.id },
    },
    { idempotencyKey: `nxeon_customer_${user.id}` },
  );
  await db.user.update({ where: { id: user.id }, data: { stripeCustomerId: customer.id } });
  return customer.id;
}

/**
 * Hosted Checkout session in `mode: "setup"` — how a customer saves a card.
 *
 * Checkout rather than Stripe Elements because there is no Elements/Stripe.js
 * integration anywhere in this codebase and no publishable key plumbed to the
 * browser; a redirect to Stripe's own page reuses the exact flow that already
 * takes money for deploys, upgrades and top-ups.
 *
 * `usage: "off_session"` is load-bearing: it records a mandate that covers the
 * unattended renewal charges we make later. Without it many issuers (and every
 * SCA-regulated card) reject the first off-session charge outright, which would
 * turn "saved card" into "card that is declined once a month".
 */
export async function createCardSetupSession(
  user: CardUser,
  returnPath = "/dashboard/billing",
): Promise<string | null> {
  if (!stripeConfigured()) return null;
  const customerId = await ensureStripeCustomer(user);
  const base = appBase();
  const session = await stripe().checkout.sessions.create({
    mode: "setup",
    customer: customerId,
    payment_method_types: ["card"],
    setup_intent_data: { usage: "off_session", metadata: { nxeonUserId: user.id } },
    metadata: { nxeonUserId: user.id, nxeonCardSetup: "1" },
    // Deliberately NOT /api/stripe/confirm. A setup session has no amount and
    // `payment_status: "unpaid"`, so the shared fulfil path would classify it as a
    // wallet top-up and flash "Payment received — your balance updates within
    // seconds" at someone who only saved a card. We finalise through our own
    // server action instead.
    success_url: `${base}${returnPath}?card_setup={CHECKOUT_SESSION_ID}`,
    cancel_url: `${base}${returnPath}?card_setup=canceled`,
  });
  return session.url;
}

/** Mirror the display fields + payment method for a card onto the account. */
async function persistCard(userId: string, customerId: string, pm: Stripe.PaymentMethod) {
  await db.user.update({
    where: { id: userId },
    data: {
      stripeCustomerId: customerId,
      stripePaymentMethodId: pm.id,
      cardBrand: pm.card?.brand ?? null,
      cardLast4: pm.card?.last4 ?? null,
      cardExpMonth: pm.card?.exp_month ?? null,
      cardExpYear: pm.card?.exp_year ?? null,
      // A brand-new card gets a fresh expiry-warning budget, otherwise a customer
      // who replaces an expiring card would never be warned about the new one.
      cardExpiryNotifiedAt: null,
    },
  });
}

export type SavedCard = { brand: string | null; last4: string | null; expMonth: number | null; expYear: number | null };

/**
 * Finalise a completed setup Checkout session: read the payment method off it,
 * make it the customer's default and mirror it onto the account.
 *
 * Verifies `metadata.nxeonUserId` against the caller. The session id travels in a
 * URL the customer can edit, so without that check a customer could paste someone
 * else's session id and attach their card to their own account.
 */
export async function saveCardFromSetupSession(
  sessionId: string,
  userId: string,
): Promise<{ card?: SavedCard; error?: string }> {
  if (!stripeConfigured()) return { error: "Card payments are not configured." };
  let session: Stripe.Checkout.Session;
  try {
    session = await stripe().checkout.sessions.retrieve(sessionId, { expand: ["setup_intent"] });
  } catch {
    return { error: "We couldn't read that card setup. Try adding the card again." };
  }
  if (session.mode !== "setup" || session.metadata?.nxeonUserId !== userId) {
    return { error: "That card setup doesn't belong to this account." };
  }
  if (session.status !== "complete") {
    return { error: "The card wasn't saved — the setup wasn't completed." };
  }
  const setupIntent = session.setup_intent as Stripe.SetupIntent | string | null;
  const pmRef =
    typeof setupIntent === "string" ? null : (setupIntent?.payment_method ?? null);
  const pmId = typeof pmRef === "string" ? pmRef : (pmRef?.id ?? null);
  const customerId =
    typeof session.customer === "string" ? session.customer : (session.customer?.id ?? null);
  if (!pmId || !customerId) return { error: "The card wasn't saved — no payment method came back." };

  const pm = await stripe().paymentMethods.retrieve(pmId);
  // Checkout already attached the method to the customer; making it the default
  // means the adoption backstop below and anything Stripe-side pick the same card.
  await stripe()
    .customers.update(customerId, { invoice_settings: { default_payment_method: pmId } })
    .catch(() => {
      /* non-fatal: our own stripePaymentMethodId is the source of truth for charging */
    });
  await persistCard(userId, customerId, pm);
  return {
    card: {
      brand: pm.card?.brand ?? null,
      last4: pm.card?.last4 ?? null,
      expMonth: pm.card?.exp_month ?? null,
      expYear: pm.card?.exp_year ?? null,
    },
  };
}

/**
 * Backstop for the closed-tab case.
 *
 * Checkout attaches the card to the Stripe customer BEFORE our `success_url` ever
 * runs. A customer who completes the Stripe page and then closes the tab has a
 * perfectly good card on file at Stripe and none on file here — and would be
 * dunned and suspended for it. This is the same class of bug as the Stripe
 * fulfilment incident: a browser redirect must never be the only trigger.
 *
 * Adoption is deliberately narrow. It requires a `card.setup_started` audit row
 * newer than any `card.removed` row and no older than a week, so a card the
 * customer explicitly REMOVED can never be silently resurrected and charged.
 */
export async function adoptUnclaimedCards(now = new Date()): Promise<number> {
  if (!stripeConfigured()) return 0;
  const since = new Date(now.getTime() - SETUP_INTENT_TTL_DAYS * 86400_000);
  const starts = await db.auditLog.findMany({
    where: { action: CARD_SETUP_STARTED, createdAt: { gt: since } },
    orderBy: { createdAt: "desc" },
    take: 200,
  });
  const userIds = [...new Set(starts.map((a) => a.userId).filter((v): v is string => !!v))];
  if (userIds.length === 0) return 0;

  let adopted = 0;
  for (const userId of userIds) {
    const user = await db.user.findUnique({ where: { id: userId } });
    if (!user?.stripeCustomerId || user.stripePaymentMethodId) continue;

    const startedAt = starts.find((a) => a.userId === userId)!.createdAt;
    const removed = await db.auditLog.findFirst({
      where: { userId, action: CARD_REMOVED },
      orderBy: { createdAt: "desc" },
    });
    if (removed && removed.createdAt > startedAt) continue; // removal is the later intent

    try {
      const list = await stripe().paymentMethods.list({
        customer: user.stripeCustomerId,
        type: "card",
        limit: 5,
      });
      const pm = list.data[0]; // newest first
      if (!pm) continue;
      await persistCard(userId, user.stripeCustomerId, pm);
      await db.auditLog.create({
        data: {
          userId,
          action: "card.adopted",
          detail: `${cardDisplayLabel({
            brand: pm.card?.brand ?? null,
            last4: pm.card?.last4 ?? null,
            expMonth: pm.card?.exp_month ?? null,
            expYear: pm.card?.exp_year ?? null,
          })} (saved at Stripe but never confirmed in the browser)`,
        },
      });
      adopted++;
    } catch (e) {
      console.error(`[cards] could not adopt card for ${userId}`, e);
    }
  }
  return adopted;
}

/**
 * Remove the saved card: detach at Stripe FIRST, and only clear our columns once
 * Stripe agrees the method is gone. Clearing locally while the method is still
 * attached would let `adoptUnclaimedCards` re-adopt it and charge a card the
 * customer had removed. A method that is already missing counts as removed.
 */
export async function detachSavedCard(userId: string): Promise<{ ok?: true; error?: string }> {
  const user = await db.user.findUnique({ where: { id: userId } });
  if (!user) return { error: "Account not found." };
  if (!user.stripePaymentMethodId) {
    await clearCardColumns(userId);
    return { ok: true };
  }
  if (stripeConfigured()) {
    try {
      await stripe().paymentMethods.detach(user.stripePaymentMethodId);
    } catch (e) {
      const err = asStripeError(e);
      if (err?.code !== "resource_missing") {
        console.error("[cards] detach failed", e);
        return { error: "We couldn't remove the card just now. Please try again in a moment." };
      }
    }
  }
  await clearCardColumns(userId);
  return { ok: true };
}

async function clearCardColumns(userId: string) {
  await db.user.update({
    where: { id: userId },
    data: {
      stripePaymentMethodId: null,
      cardBrand: null,
      cardLast4: null,
      cardExpMonth: null,
      cardExpYear: null,
      cardExpiryNotifiedAt: null,
    },
  });
}

/**
 * A customer who saves a card mid-dunning has been told (by
 * `emails.paymentFailed`) that we'll "charge it straight away". Bringing the
 * scheduled retry forward is what makes that copy true — the next sweep picks it
 * up instead of waiting for the day-3 or day-5 slot. The failure COUNT is left
 * alone: the money is still owed.
 */
export async function retryDunningNow(userId: string): Promise<number> {
  const res = await db.server.updateMany({
    where: { userId, dunningStage: { gt: 0 } },
    data: { dunningNextAt: new Date() },
  });
  return res.count;
}

/* ------------------------------------------------------------------ *
 * Off-session charging
 * ------------------------------------------------------------------ */

type StripeErrorLike = {
  type?: string;
  rawType?: string;
  code?: string;
  decline_code?: string;
  message?: string;
  payment_intent?: { id?: string; status?: string };
};

function asStripeError(e: unknown): StripeErrorLike | null {
  if (!e || typeof e !== "object") return null;
  const err = e as StripeErrorLike;
  return err.rawType || err.type?.startsWith("Stripe") ? err : null;
}

export type OffSessionResult =
  /** Money captured. `amountCents` is what Stripe actually took, not what we asked for. */
  | { ok: true; paymentIntentId: string; amountCents: number; replayed: boolean }
  /** 3-D Secure or equivalent: the customer must approve it with their bank. */
  | { ok: false; kind: "requires_action"; paymentIntentId: string | null; message: string }
  /** The issuer said no. A real dunning event. */
  | { ok: false; kind: "declined"; message: string; code?: string }
  /** Our side or Stripe's side wobbled. NOT the customer's fault — never dun for it. */
  | { ok: false; kind: "transient"; message: string }
  /** Nothing to charge with (no card, Stripe off, amount under Stripe's floor). */
  | { ok: false; kind: "unavailable"; message: string };

/**
 * Stable per-purpose marker written into PaymentIntent metadata.
 *
 * This is a SECOND idempotency guard that does not expire. Stripe's own
 * idempotency keys are only honoured for 24 hours, and our dunning schedule spans
 * six days, so the key alone cannot answer "have we already been paid for this
 * period?". Before charging we look for a live PaymentIntent carrying this marker
 * and reuse it — so a crash between "Stripe captured the money" and "we recorded
 * the payment intent id" can never turn into a second charge.
 */
export function renewalChargeMarker(serverId: string, periodStart: Date): string {
  return `renew:${serverId}:${periodStart.toISOString()}`;
}

/** Marker for an automatic wallet top-up: at most one per account per day. */
export function autoRechargeMarker(userId: string, now: Date): string {
  return `autorecharge:${userId}:${now.toISOString().slice(0, 10)}`;
}

/** Look for a charge we may already have made for this exact purpose. */
async function findChargeByMarker(
  customerId: string,
  marker: string,
): Promise<Stripe.PaymentIntent | null> {
  // 25 is generous: renewals are monthly and this is scoped to one customer, so a
  // charge made minutes or days ago is always inside this window.
  const list = await stripe().paymentIntents.list({ customer: customerId, limit: 25 });
  const mine = list.data.filter((pi) => pi.metadata?.nxeonChargeKey === marker);
  return (
    mine.find((pi) => pi.status === "succeeded") ??
    mine.find((pi) => pi.status === "requires_action") ??
    mine.find((pi) => pi.status === "processing") ??
    null
  );
}

/**
 * Charge the saved card off-session (no customer present).
 *
 * Two independent idempotency guards, because this moves real money on a timer
 * that retries:
 *  1. `marker` — pre-flight lookup of a live PaymentIntent for this exact purpose.
 *     Survives forever, catches the crash-after-capture window.
 *  2. `idempotencyKey` — Stripe replays the identical request instead of charging
 *     twice when two sweeps overlap. Only good for 24h, hence guard 1.
 */
export async function chargeSavedCardOffSession(opts: {
  user: CardUser;
  amountCents: number;
  description: string;
  marker: string;
  idempotencyKey: string;
  metadata?: Record<string, string>;
}): Promise<OffSessionResult> {
  const { user, amountCents, description, marker, idempotencyKey } = opts;
  if (!stripeConfigured()) return { ok: false, kind: "unavailable", message: "Stripe is not configured" };
  if (!user.stripeCustomerId || !user.stripePaymentMethodId) {
    return { ok: false, kind: "unavailable", message: "No saved card" };
  }
  // `walletSplit` already keeps the card leg at or above Stripe's floor; this is
  // the belt-and-braces check so a future caller can't send a rejectable amount.
  if (amountCents < STRIPE_MIN_CENTS) {
    return { ok: false, kind: "unavailable", message: `Below Stripe minimum (${STRIPE_MIN_CENTS}c)` };
  }

  // Guard 1: did we already charge for this purpose?
  try {
    const existing = await findChargeByMarker(user.stripeCustomerId, marker);
    if (existing?.status === "succeeded") {
      return {
        ok: true,
        paymentIntentId: existing.id,
        amountCents: existing.amount_received || existing.amount,
        replayed: true,
      };
    }
    if (existing?.status === "requires_action") {
      return {
        ok: false,
        kind: "requires_action",
        paymentIntentId: existing.id,
        message: "Awaiting bank confirmation",
      };
    }
    if (existing?.status === "processing") {
      return { ok: false, kind: "transient", message: "A charge for this period is still settling" };
    }
  } catch (e) {
    // A failed lookup must not become a blind second charge.
    console.error("[cards] pre-flight charge lookup failed", e);
    return { ok: false, kind: "transient", message: "Could not verify existing charges" };
  }

  try {
    const pi = await stripe().paymentIntents.create(
      {
        amount: amountCents,
        currency: "usd",
        customer: user.stripeCustomerId,
        payment_method: user.stripePaymentMethodId,
        confirm: true,
        off_session: true,
        // No browser exists here, so a redirect-based next_action could never be
        // satisfied — and asking for one is what makes Stripe demand a return_url.
        automatic_payment_methods: { enabled: true, allow_redirects: "never" },
        description,
        metadata: { ...(opts.metadata ?? {}), nxeonUserId: user.id, nxeonChargeKey: marker },
      },
      { idempotencyKey },
    );
    if (pi.status === "succeeded") {
      return { ok: true, paymentIntentId: pi.id, amountCents: pi.amount_received || pi.amount, replayed: false };
    }
    if (pi.status === "requires_action" || pi.status === "requires_confirmation") {
      return { ok: false, kind: "requires_action", paymentIntentId: pi.id, message: "Bank confirmation required" };
    }
    if (pi.status === "processing") {
      return { ok: false, kind: "transient", message: "Payment is still processing" };
    }
    return { ok: false, kind: "declined", message: `Payment could not be completed (${pi.status})` };
  } catch (e) {
    return classifyChargeError(e);
  }
}

/**
 * Split a charge failure into the three cases that deserve different treatment:
 * the bank wants the customer to confirm, the bank said no, or nothing about the
 * customer went wrong at all.
 *
 * The default is `transient` on purpose. A misclassified transient error costs us
 * a delayed renewal; a misclassified decline costs a paid-up customer their
 * server. Unknown always resolves to the direction that cannot suspend anyone.
 */
function classifyChargeError(e: unknown): OffSessionResult {
  const err = asStripeError(e);
  const message = String(err?.message ?? (e as Error)?.message ?? e).slice(0, 300);
  if (!err) return { ok: false, kind: "transient", message };

  // 3-D Secure surfaces as a card error with this code, with the PI attached.
  if (err.code === "authentication_required" || err.payment_intent?.status === "requires_action") {
    return {
      ok: false,
      kind: "requires_action",
      paymentIntentId: err.payment_intent?.id ?? null,
      message,
    };
  }
  if (err.rawType === "card_error") {
    return { ok: false, kind: "declined", message, code: err.decline_code ?? err.code };
  }
  // The saved method vanished at Stripe (detached elsewhere, customer deleted).
  // Not a decline — there is nothing to retry until a new card is saved.
  if (err.rawType === "invalid_request_error" && err.code === "resource_missing") {
    return { ok: false, kind: "unavailable", message };
  }
  return { ok: false, kind: "transient", message };
}

/** Drop a stale payment method so the UI stops claiming a card is on file. */
export async function forgetMissingPaymentMethod(userId: string): Promise<void> {
  await clearCardColumns(userId);
  await db.auditLog.create({
    data: {
      userId,
      action: "card.missing_at_stripe",
      detail: "Saved payment method no longer exists at Stripe — cleared locally",
    },
  });
}

/**
 * Credit the wallet for money a card just paid, exactly once.
 *
 * Idempotency is the UNIQUE index on `WalletTransaction.stripePaymentIntentId`,
 * NOT a read-then-write check: a retried sweep and a replayed Stripe request can
 * both arrive with the same intent id, and only the database can safely pick the
 * winner. P2002 means someone already credited it — that is a success, not an error.
 *
 * No invoice for a renewal leg: the renewal transaction issues one PAID invoice
 * for the whole renewal, and a second document for the card portion would
 * double-count the same revenue. Callers that ARE the whole payment (a wallet
 * auto-top-up) pass `invoiceDescription` and get one in the same guarded write.
 */
export async function creditOffSessionCharge(opts: {
  userId: string;
  amountCents: number;
  description: string;
  paymentIntentId: string;
  invoiceDescription?: string;
}): Promise<boolean> {
  if (opts.amountCents <= 0) return false;
  try {
    await db.$transaction([
      db.walletTransaction.create({
        data: {
          userId: opts.userId,
          amountCents: opts.amountCents,
          description: opts.description,
          stripePaymentIntentId: opts.paymentIntentId,
        },
      }),
      db.user.update({
        where: { id: opts.userId },
        data: { balanceCents: { increment: opts.amountCents } },
      }),
      ...(opts.invoiceDescription
        ? [
            db.invoice.create({
              data: invoiceCreateData({
                userId: opts.userId,
                description: opts.invoiceDescription,
                status: "PAID",
                lineItems: [
                  {
                    description: opts.invoiceDescription,
                    qty: 1,
                    unitCents: opts.amountCents,
                    amountCents: opts.amountCents,
                  },
                ],
              }),
            }),
          ]
        : []),
    ]);
    return true;
  } catch (e) {
    if ((e as { code?: string })?.code === "P2002") return false; // already credited
    throw e;
  }
}

/**
 * Hosted Checkout link for an outstanding renewal balance.
 *
 * Carries ONLY `nxeonUserId` in metadata, which makes the shared, already-proven
 * fulfilment path treat it as a wallet top-up: the money lands as wallet credit
 * and the next sweep renews from the wallet. That is why this is also the answer
 * to 3-D Secure — Checkout collects the bank challenge on Stripe's own page, so we
 * never need Stripe.js in the browser or a second confirmation code path.
 *
 * The quoted amount is the remainder the wallet cannot cover AT THIS MOMENT. If
 * the customer spends their credit before paying, the next sweep simply recomputes
 * the split and asks the card for the new remainder — it self-heals rather than
 * over- or under-charging.
 */
export async function createOutstandingCheckout(opts: {
  user: { id: string; email: string; stripeCustomerId: string | null };
  amountCents: number;
  hostname: string;
  serverId: string;
}): Promise<string | null> {
  if (!stripeConfigured()) return null;
  const amount = Math.max(STRIPE_MIN_CENTS, Math.round(opts.amountCents));
  if (amount <= 0) return null;
  const base = appBase();
  try {
    const session = await stripe().checkout.sessions.create({
      mode: "payment",
      ...(opts.user.stripeCustomerId
        ? { customer: opts.user.stripeCustomerId }
        : { customer_email: opts.user.email }),
      line_items: [
        {
          price_data: {
            currency: "usd",
            product_data: {
              name: `Nxeon renewal — ${opts.hostname}`,
              description:
                "Settles the outstanding renewal balance. Added to your Nxeon wallet and applied to this renewal automatically.",
            },
            unit_amount: amount,
          },
          quantity: 1,
        },
      ],
      metadata: { nxeonUserId: opts.user.id },
      success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
      cancel_url: `${base}/dashboard/servers/${opts.serverId}`,
    });
    return session.url;
  } catch (e) {
    console.error("[cards] could not create outstanding-balance checkout", e);
    return null;
  }
}

/**
 * Best-effort cleanup of a 3-D Secure intent we have given up on.
 *
 * Once the customer settles through the hosted link, an abandoned
 * `requires_action` intent is a loaded gun: anything that later confirms it takes
 * a second payment for a period that is already paid. Cancelling is only ever
 * attempted while it is still unconfirmed, so no captured money is touched.
 */
export async function cancelPendingAction(paymentIntentId: string | null): Promise<void> {
  if (!paymentIntentId || !stripeConfigured()) return;
  try {
    const pi = await stripe().paymentIntents.retrieve(paymentIntentId);
    if (pi.status === "requires_action" || pi.status === "requires_confirmation") {
      await stripe().paymentIntents.cancel(paymentIntentId);
    }
  } catch {
    /* best-effort — an uncancelled intent is inert unless someone confirms it */
  }
}

