/**
 * Cancel a PaymentIntent, but only while it is still unconfirmed — captured money
 * is never touched. Best-effort throughout: an uncancelled intent is inert unless
 * something confirms it, and nothing in this codebase ever does.
 */
async function cancelIfUnconfirmed(paymentIntentId: string): Promise<void> {
  try {
    const pi = await stripe().paymentIntents.retrieve(paymentIntentId);
    if (pi.status === "requires_action" || pi.status === "requires_confirmation") {
      await stripe().paymentIntents.cancel(paymentIntentId);
    }
  } catch {
    /* best-effort */
  }
}

/**
 * Clean up an abandoned 3-D Secure challenge once its period has been paid another
 * way (usually the hosted link).
 *
 * A leftover `requires_action` intent is a loaded gun: anything that later confirms
 * it takes a second payment for a period that is already settled.
 */
export async function cancelPendingChargeForMarker(
  customerId: string | null,
  marker: string,
): Promise<void> {
  if (!customerId || !stripeConfigured()) return;
  try {
    const list = await stripe().paymentIntents.list({ customer: customerId, limit: 25 });
    for (const pi of list.data) {
      if (pi.metadata?.nxeonChargeKey !== marker) continue;
      if (pi.status === "requires_action" || pi.status === "requires_confirmation") {
        await cancelIfUnconfirmed(pi.id);
      }
    }
  } catch {
    /* best-effort */
  }
}

